template <typename MaybeConstUserType, SendValidation send_validation>
struct SendValidationSerializer<::ai_chat::mojom::ActionEntryDataView, MaybeConstUserType, send_validation> {
  using UserType = typename std::remove_const<MaybeConstUserType>::type;
  using Traits = UnionTraits<::ai_chat::mojom::ActionEntryDataView, UserType>;
  static void Serialize(MaybeConstUserType& input,
                        MessageFragment<::ai_chat::mojom::internal::ActionEntry_Data>& fragment,
                        bool inlined) {
    
    if (CallIsNullIfExists<Traits>(input)) {
       if (inlined)
        fragment->set_null();
      return;
    }

if (!inlined)
  fragment.Allocate();

    // TODO(azani): Handle unknown and objects.
    // Set the not-null flag.
fragment->size = kUnionDataSize;
fragment->tag = Traits::GetTag(input);
switch (fragment->tag) {
  case ::ai_chat::mojom::ActionEntryDataView::Tag::kSubheading: {
    decltype(Traits::subheading(input))
    in_subheading = Traits::subheading(input);
    mojo::internal::MessageFragment<
      typename decltype(fragment->data.f_subheading)::BaseType>
    value_fragment(fragment.message());
        
mojo::internal::Serialize<mojo::StringDataView, send_validation>(
  in_subheading,
  value_fragment);
  
MOJO_INTERNAL_CHECK_SERIALIZATION(
  send_validation,
  !(value_fragment.is_null()),
  mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
  "null subheading in ActionEntry union");
    fragment->data.f_subheading.Set(
      value_fragment.is_null() ? nullptr : value_fragment.data());
    break;
  }
  case ::ai_chat::mojom::ActionEntryDataView::Tag::kDetails: {
    decltype(Traits::details(input))
    in_details = Traits::details(input);
    mojo::internal::MessageFragment<
      typename decltype(fragment->data.f_details)::BaseType>
    value_fragment(fragment.message());
        
mojo::internal::Serialize<::ai_chat::mojom::ActionDetailsDataView, send_validation>(
  in_details,
  value_fragment);
  
MOJO_INTERNAL_CHECK_SERIALIZATION(
  send_validation,
  !(value_fragment.is_null()),
  mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
  "null details in ActionEntry union");
    fragment->data.f_details.Set(
      value_fragment.is_null() ? nullptr : value_fragment.data());
    break;
  }
}
  }
};

